(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.018+t*0.28)*18 + Math.cos(y*0.013-t*0.19)*12;
  const w1y = Math.cos(y*0.019-t*0.22)*18 + Math.sin(x*0.016+t*0.31)*12;
  const w2x = Math.sin((x+y)*0.012+t*0.4)*8 + Math.cos((x-y)*0.01-t*0.35)*6;
  const w2y = Math.cos((x-y)*0.011-t*0.38)*8 + Math.sin((x+y)*0.009+t*0.42)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.55)*110, 75+Math.cos(t*0.38)*55, 0.075, 2.1, 0.8],
    [325+Math.cos(t*0.48)*105, 165+Math.sin(t*0.65)*55, 0.095, 1.8, 1.0],
    [235+Math.sin(t*0.28+2)*145, 115+Math.cos(t*0.45+1)*95, 0.055, 2.4, 0.6],
    [115+Math.cos(t*0.75+1)*85, 185+Math.sin(t*0.58+3)*65, 0.115, 1.6, 1.2],
    [365+Math.sin(t*0.38+4)*95, 55+Math.cos(t*0.85+2)*75, 0.065, 2.7, 0.7],
    [245+Math.cos(t*0.32+5)*125, 205+Math.sin(t*0.52)*85, 0.085, 2.0, 0.9],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.7+1)*50, 0.13, 1.4, 1.1],
    [400+Math.cos(t*0.42+2)*80, 200+Math.sin(t*0.78+4)*60, 0.07, 2.5, 0.75]
  ];
  let aS=0, iS=0, cS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wv = Math.sin(d*f-t*sp);
    aS += wv * w;
    iS += Math.sin(d*f*0.65+t*sp*0.55+1.7) * w;
    cS += Math.sin(d*f*1.3-t*sp*0.8+2.5) * w * 0.5;
  }
  const tw = src.reduce((a,s)=>a+s[4],0);
  aS/=tw; iS/=tw; cS/=tw;
  const bg1 = (Math.sin(sx*0.035+sy*0.022+t*0.75)+Math.sin(sx*0.028-sy*0.038+t*1.05))/2;
  const bg2 = Math.sin((sx+sy)*0.11+t*2.3)*0.2+Math.sin((sx-sy)*0.095-t*1.8)*0.2;
  const bg3 = Math.sin(sx*0.06+Math.cos(sy*0.04+t)*2+t*1.5)*0.15;
  const bg = bg1+bg2+bg3;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy,sx-cx);
  const sp1 = Math.sin(dist*0.045-ang*3.5-t*1.4);
  const sp2 = Math.sin(dist*0.038+ang*4.5-t*1.1);
  const sp3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.3;
  const spiral = (sp1+sp2)*0.35+sp3;
  const feed = 0.055+Math.sin(dist*0.008+t*0.3)*0.015;
  const kill = 0.062+Math.cos(ang*2+t*0.2)*0.008;
  const lap = aS*0.4+iS*-0.3+cS*0.2+bg*0.25+spiral;
  const rd = Math.tanh((lap+(feed-kill)*3)*2.5);
  const cellX = sx*0.14, cellY = sy*0.14;
  const voro = Math.sin(cellX)*Math.sin(cellY)+Math.sin((cellX+cellY)*0.7+t*0.6)*0.4;
  const cell = Math.tanh(voro*1.8)*0.35;
  const detail = Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend = rd*0.6+cell*0.3+detail;
  const edge = 1.0-Math.pow(1.0-Math.abs(rd),3)*0.5;
  const glow = Math.pow(Math.max(0,Math.abs(rd)-0.6)*2.5,1.5);
  const v = blend*0.5+0.5;
  const pal = [
    [5,12,45],[10,35,85],[12,65,120],[18,110,135],
    [30,155,140],[80,180,120],[170,195,80],
    [220,180,55],[235,140,60],[215,90,65],
    [180,50,70],[120,30,75],[65,20,60],[30,15,50],[5,12,45]
  ];
  const idx = v*(pal.length-1);
  const i = Math.min(idx|0, pal.length-2);
  const f = idx-i;
  const cShift = cS*0.08;
  const i2 = Math.min(Math.max(0,i+Math.round(cShift)),pal.length-2);
  const f2 = Math.max(0,Math.min(1,f+Math.abs(cShift)%1));
  const r = pal[i2][0]+(pal[i2+1][0]-pal[i2][0])*f2;
  const g = pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b = pal[Math.min(i-Math.round(cShift*0.5),pal.length-2)][2]+(pal[Math.min(i-Math.round(cShift*0.5)+1,pal.length-1)][2]-pal[Math.min(i-Math.round(cShift*0.5),pal.length-2)][2])*f;
  const lum = 0.85+Math.sin(rd*Math.PI)*0.15+glow*0.4;
  const ef = edge*1.1+glow*0.5;
  return [
    Math.min(255,(r*lum*ef+glow*30)|0),
    Math.min(255,(g*lum*ef+glow*20)|0),
    Math.min(255,(b*lum*ef+glow*45)|0)
  ];
}
